import type { Card, CardsFile, CardsFileCard, Goal, Moment } from "../catalog";

/**
 * Builders for test data in the same shape as `data/tarjetas.json`
 * (Spanish keys, as generated by `scripts/calcular.py --json`), and for what
 * the app stores in a Day from it.
 */

export const goalsFixture: CardsFile["objetivos"] = {
  diario: { kcal: 1900, prot: 180, carb: 175, grasa: 56, fibra_min: 30 },
  tolerancia: { kcal_pct: 5, macro_g: 5 },
  momentos: {
    desayuno: { kcal: 400, prot: 35, carb: 45, grasa: 9 },
    almuerzo: { kcal: 600, prot: 55, carb: 55, grasa: 18 },
    merienda: { kcal: 300, prot: 35, carb: 25, grasa: 7 },
    cena: { kcal: 600, prot: 55, carb: 50, grasa: 22 },
  },
};

/** `goalsFixture` as a Day stores it. */
export const goalFixture: Goal = {
  daily: { kcal: 1900, protein: 180, carbs: 175, fat: 56, fiberMin: 30 },
  moments: {
    breakfast: { kcal: 400, protein: 35, carbs: 45, fat: 9 },
    lunch: { kcal: 600, protein: 55, carbs: 55, fat: 18 },
    snack: { kcal: 300, protein: 35, carbs: 25, fat: 7 },
    dinner: { kcal: 600, protein: 55, carbs: 50, fat: 22 },
  },
};

let nextId = 1;

export function cardFixture(overrides: Partial<CardsFileCard> = {}): CardsFileCard {
  const id = overrides.id ?? `card-${nextId++}`;
  return {
    id,
    momento: "desayuno",
    tipo: "dulce",
    nombre: `Tarjeta ${id}`,
    ingredientes: [{ id: "avena", g: 40, nombre: "Copos de avena", categoria: "cereal" }],
    preparacion: "Mezclar y calentar.",
    nutricion: { kcal: 400, prot: 35, carb: 45, grasa: 9, fibra: 5 },
    ...overrides,
  };
}

export function cardsFileFixture(cards: CardsFileCard[]): CardsFile {
  return { objetivos: goalsFixture, tarjetas: cards };
}

const MOMENT_BY_FILE_MOMENT: Record<string, Moment> = {
  desayuno: "breakfast",
  almuerzo: "lunch",
  merienda: "snack",
  cena: "dinner",
};

/**
 * The Choice that confirming the Card `id` of `cardsFile` stores (a frozen copy of the
 * Card, ADR-0002): for seeding the repository as if it had been confirmed earlier.
 */
export function choiceFixture(cardsFile: CardsFile, id: string): Card {
  const card = cardsFile.tarjetas.find((c) => c.id === id);
  if (!card) throw new Error(`No Card "${id}" in the fixture`);
  return {
    id: card.id,
    moment: MOMENT_BY_FILE_MOMENT[card.momento],
    kind: card.tipo === "dulce" ? "sweet" : "savory",
    name: card.nombre,
    ingredients: card.ingredientes.map((i) => ({
      id: i.id,
      name: i.nombre,
      grams: i.g,
      category: i.categoria,
      ...(i.unidad_casera ? { householdUnit: i.unidad_casera } : {}),
    })),
    preparation: card.preparacion,
    nutrition: {
      kcal: card.nutricion.kcal,
      protein: card.nutricion.prot,
      carbs: card.nutricion.carb,
      fat: card.nutricion.grasa,
      fiber: card.nutricion.fibra,
    },
  };
}
